!function(e){function t(t){for(var a,n,m=t[0],d=t[1],p=t[2],y=0,g=[];y<m.length;y++)n=m[y],Object.prototype.hasOwnProperty.call(i,n)&&i[n]&&g.push(i[n][0]),i[n]=0;for(a in d)Object.prototype.hasOwnProperty.call(d,a)&&(e[a]=d[a]);for(s&&s(t);g.length;)g.shift()();return o.push.apply(o,p||[]),r()}function r(){for(var e,t=0;t<o.length;t++){for(var r,n=o[t],m=!0,d=1;d<n.length;d++)r=n[d],0!==i[r]&&(m=!1);m&&(o.splice(t--,1),e=a(a.s=n[0]))}return e}function a(t){if(n[t])return n[t].exports;var r=n[t]={i:t,l:!1,exports:{}};return e[t].call(r.exports,r,r.exports,a),r.l=!0,r.exports}var n={},i={85:0},o=[];a.m=e,a.c=n,a.d=function(e,t,r){a.o(e,t)||Object.defineProperty(e,t,{enumerable:!0,get:r})},a.r=function(e){"undefined"!=typeof Symbol&&Symbol.toStringTag&&Object.defineProperty(e,Symbol.toStringTag,{value:"Module"}),Object.defineProperty(e,"__esModule",{value:!0})},a.t=function(e,t){if(1&t&&(e=a(e)),8&t)return e;if(4&t&&"object"==typeof e&&e&&e.__esModule)return e;var r=Object.create(null);if(a.r(r),Object.defineProperty(r,"default",{enumerable:!0,value:e}),2&t&&"string"!=typeof e)for(var n in e)a.d(r,n,function(t){return e[t]}.bind(null,n));return r},a.n=function(e){var t=e&&e.__esModule?function(){return e.default}:function(){return e};return a.d(t,"a",t),t},a.o=function(e,t){return Object.prototype.hasOwnProperty.call(e,t)},a.p="";var m=window.webpackJsonp=window.webpackJsonp||[],d=m.push.bind(m);m.push=t,m=m.slice();for(var p=0;p<m.length;p++)t(m[p]);var s=d;o.push([48,0]),r()}({48:function(e,t,r){"use strict";r.r(t);var a=r(0);Object(a.a)("de","army",r(49),r(1))},49:function(e){e.exports=JSON.parse('{"category":[{"name":"德国","link":"de_shortcut"},{"name":"陆战武器","link":"de_army"},{"name":"坦克歼击车","link":"de_army#de_army_tankdestroyer"}],"model":"“费迪南德”/“象”式坦克歼击车","description":"<p>1942年，保时捷公司与谢亨尔公司参与了虎Ⅰ型坦克的研制，但德军最终采用了谢亨尔公司的样车，因此保时捷公司就将为研制虎Ⅰ型坦克过程中所生产的约90辆VK4501（P）底盘装上一门88mm火炮，成为反坦克自行炮车，该炮车开始称为“费迪南德”（保时捷.费迪南德博士是一位非常有才华的坦克设计师，1939年被任命为德国坦克发展委员会的首席），“费迪南德”坦克歼击车首次参战是东线苏联库尔斯克战场，653和654两个重装甲歼击营携带全部90辆“费迪南德”坦克歼击车参加了坦克会战，但由于当时该车没有安装机枪，在会战中被苏军反坦克武器近距离攻击爆破，损失极大；德军吸取教训，立刻给“费迪南德”坦克歼击车配上了2挺MG34机枪，改名“象”式坦克歼击车，继续在东线战场与意大利战场上重新投入了战斗，在战场中表现不错。</p>","part1title":"","part1description":"","part1content":[{"image":"{{text}}“费迪南德”/“象”式坦克歼击车四视图（线图）{{image}}imgs/de/army/de_army_tankdestroyerelefant_11.jpg","description":"<h6>“费迪南德”/“象”式坦克歼击车<br>型号：Ferdinand/Elefant（Sdkfz 184）</h6><p>参数：车长：8.14m，车宽：3.38m，车高：2.97m，车重：65.0t；乘员：6人。</p><p>最高车速：30km/h，最大行程：150km；</p><p>装甲厚度：前装甲与驾驶室正面装甲为200mm，侧后装甲为80mm。</p><p>武器配备：1门88mm Pak43/2  L/71X1型火炮；火炮射界为-8～+14度，方向射界为左右各14度，炮弹基数为55发。</p><p>“象”式加装 2挺MG34型7.92mm机枪。）</p>","caption":""},{"image":"{{text}}“费迪南德”/“象”式坦克歼击车四视图（彩图）{{image}}imgs/de/army/de_army_tankdestroyerelefant_12.jpg","description":"<p>“费迪南德”/“象”式坦克歼击车整体布置是：前部是驾驶室，中部是动力舱，装有二台300a匹马力的发动机；后部是战斗室，战斗室空间较大。</p><p>该车装甲防御力超过了同期的虎Ⅰ型坦克与豹式坦克；其所装的88mm火炮可在500m距离上击穿30度倾角厚207mm的装甲，并可在远距离上有效地对付苏军的坦克。</p>","caption":""}],"part2title":"战场上的“费迪南德”/“象”式坦克歼击车","part2description":"","part2content":[{"image":"imgs/de/army/de_army_tankdestroyerelefant_21.jpg","description":"1943年7月东线战场，苏联奥廖尔地区，德军654重装甲歼击营第2连623号“费迪南德”坦克歼击车。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyerelefant_22.jpg","description":"1943年7、8月间，东线战场，苏联奥廖尔地区，德军654重装甲歼击营第1连511号“费迪南德”坦克歼击车。注意该车炮管前端有16道击杀环，表示该车的战绩。该车车长为费尔德海姆少尉。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyerelefant_23.jpg","description":"1943年12月，东线战场，德军654重装甲歼击营第1连一辆“费迪南德”坦克歼击车。该车已涂上冬季伪装色。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyerelefant_24.jpg","description":"1944年6月，东线波兰战场，德军654重装甲歼击营第2连一辆编号224“象”式坦克歼击车。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyerelefant_25.jpg","description":"1944年4月，东线波兰战场，德军654重装甲歼击营第3连一辆编号332“象”式坦克歼击车。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyerelefant_26.jpg","description":"库尔斯克会战（德军“堡垒”作战行动），德军643与654二个重装甲歼击营携带全部90辆“费迪南德”坦克歼击车参加了战斗。图中是1943年7月初，“堡垒”作战行动前夕，654重装甲歼击营第2连某排的“费迪南德”坦克歼击正在以单纵队的队形进入战斗位置。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyerelefant_27.jpg","description":"1943年7月初，“堡垒”作战行动前夕，653重装甲歼击营第1连的“费迪南德”坦克歼击正在进行弹药补给。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyerelefant_28.jpg","description":"1943年6月底，“堡垒”作战行动前夕，654重装甲歼击营第3连一辆全车伪装的“费迪南德”坦克歼击正在向库尔斯克战场集结。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyerelefant_29.jpg","description":"图中是1943年7月4日，德军“堡垒”作战在苏联库尔斯克地区展开，653重装甲歼击营124号“费迪南德”坦克歼击车进入攻击阵地。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyerelefant_30.jpg","description":"图中是1943年7月4日，德军“堡垒”作战行动，654重装甲歼击营营部Ⅱ03号“费迪南德”坦克歼击车向苏军第一道防线发起进攻，但几分钟后，该车就因触雷而失去行动能力，车组乘员被迫弃车。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyerelefant_31.jpg","description":"图中是1943年7月，在库尔斯克坦克会战中被击毁的隶属654重装甲歼击营2连的634号“费迪南德”坦克歼击车，两名苏军战士正从该车残骸旁经过。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyerelefant_32.jpg","description":"1943年7月库尔斯克坦克会战，苏军所拍摄的一个战场画面。图1是坦克会战后一个战场场景，战场中有2辆德军遗弃的“费迪南德”坦克歼击车，同时还有近10辆苏军的T-34坦克残骸，可见战斗的激烈程度。图2和图3分别是两辆德军遗弃的“费迪南德”坦克歼击车放大图，前面一辆（图2）火炮高高抬起，可判断车组乘员已安全撒退（因为根据德军的操作要领，乘员撒退时，炮手要将火炮抬至最大仰角，以方便驾驶员和无线电操作员打开舱盖撒退）。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyerelefant_33.jpg","description":"这是在库尔斯克坦克会战后，苏军拍摄的一张宣传用的照片，照片中是在战斗中被击毁的隶属654重装甲歼击营2连的63号“费迪南德”坦克歼击车，但作投掷手雷（RPG-4型反坦克手榴弹）状的苏军战士则是摆拍上去的。不过由于“费迪南德”坦克歼击车没有装备机枪。因此常常被苏军迫近，用反坦克武器进行近距离攻击，造成极大的损失。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyerelefant_34.jpg","description":"图1和图2是库尔斯克坦克会战后，德军遗弃在战场上隶属654重装甲歼击营Ⅱ02号“费迪南德”坦克歼击车的残骸。据苏军战报记录，该车先是被地雷炸坏了左侧履带，然后又受到苏军用燃烧瓶攻击，最后该车组乘员被迫弃车撒离。图3是1944年苏联中央方面军司令罗科索夫斯基将军等人在检查该辆坦克歼击车（此车已移离战场），该车正面还有多个被苏军用100mm野战炮轰击的测试弹痕。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyerelefant_35.jpg","description":"1943年7月苏联库尔斯克战场，德军654重装甲歼击营1连511号“费迪南德”坦克歼击车修复后正准备重返前线。该车左侧前挡板已被地雷炸飞，旁边是一辆受损的Ⅳ号坦克（隶属德军第35装甲团）。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyerelefant_36.jpg","description":"1943年库尔斯克会战以德军的失败告终，德军的堡垒行动溃败，参加行动的“费迪南德”坦克歼击车在这场战役中表现令人失望，在战役的头4天，就有21辆因故障无法参加后续战斗，而开战前6天，就有22辆“费迪南德”坦克歼击车被地雷或被反坦克武器摧毁。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyerelefant_37.jpg","description":"1943年底，德军653重装甲歼击营第3连的一辆“费迪南德”坦克歼击车正在急速往第聂伯河桥头堡疾驶，以阻挡苏军的进攻。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyerelefant_38.jpg","description":"1943年底，守卫在第聂伯河桥头堡的二辆德军653重装甲歼击营“费迪南德”坦克歼击车。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyerelefant_39.jpg","description":"1944年初，吸取库尔斯克失败的教训，德军为剩余的“费迪南德”坦克歼击车装上了2挺MG34机枪，车改名“象”式，并陆续分配给653等重装甲歼击营，图中为653重装甲歼击营第3连的一辆“象”式坦克歼击车与车组乘员。车体上可清楚见到为车身所加的防磁涂层。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyerelefant_40.jpg","description":"一辆“象”坦克歼击车正在进行迷彩喷涂。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyerelefant_41.jpg","description":"1944年2月，美军在意大利安齐奥和内图诺发起登陆战，德军653重装甲歼击连携11辆经过大修和改造的“费迪南德”/象式坦克歼击车由火车运输赶赴意大利战场。到达意大利后，由于当地暴雨连连，公路泥土松软，重型歼击车难以行动，使德军原反攻计划被迫推迟。图2、3中一辆“象”式在行进中被陷在路旁抛锚，在战车旁边经过的是“戈林”伞兵装甲师的士兵。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyerelefant_42.jpg","description":"1944年2月29日，意大利战场，德军发起反攻，653重装甲歼击营第3连一辆“象”式坦克歼击车正在迫近美军阵地，一名德军掷弹兵趴伏在车旁跟随前进。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyerelefant_43.jpg","description":"1944年2月29日，意大利战场，653重装甲歼击营111号“象”式坦克歼击车在行进中被地雷炸毁，该辆车后被德军拖回后方维修；公路远处是一支德军的豹式坦克纵队。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyerelefant_44.jpg","description":"1944年8月，东线苏联战场，653重装甲歼击营一辆“象”式坦克歼击车在撒退途中暂作停留，车组乘员正在车上观察。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyerelefant_45.jpg","description":"1944年夏季，东线苏联战场。图1：2辆653重装甲歼击营的“费迪南德”坦克歼击车正在护送一个轮式装甲车队行进。图2：傍晚，2辆“费迪南德”坦克歼击车正在小山岗上警备，以防止苏军的袭击。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyerelefant_46.jpg","description":"英军正在检查一辆被击毁的隶属德军653重装甲歼击营的“象”式坦克歼击车。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyerelefant_47.jpg","description":"这辆隶属德军653重装甲歼击营编号102“象”式坦克歼击车被美军缴获后正准备运回美国，三名美军士兵与其合影留念。","caption":""}]}')}});